
create table if not exists public.repo_diver_location_catalog_2026(location_id text primary key,biome text not null,name text not null,location_type text not null,description text not null,rooms_count int not null default 5,sort_order int not null default 0);
create table if not exists public.repo_diver_artifact_catalog_2026(artifact_id text primary key,location_id text not null references public.repo_diver_location_catalog_2026(location_id) on delete cascade,name text not null,rarity text not null,required_stage int not null,lore text not null default '');
create table if not exists public.repo_diver_location_progress_2026(user_id uuid not null,location_id text not null references public.repo_diver_location_catalog_2026(location_id) on delete cascade,stage int not null default 0,discovered_at timestamptz not null default now(),completed_at timestamptz,last_run_id uuid,updated_at timestamptz not null default now(),primary key(user_id,location_id));
create table if not exists public.repo_diver_artifact_ledger_2026(user_id uuid not null,artifact_id text not null references public.repo_diver_artifact_catalog_2026(artifact_id) on delete cascade,run_id uuid,recovered_at timestamptz not null default now(),identified_at timestamptz,primary key(user_id,artifact_id));
create table if not exists public.repo_diver_location_firsts_2026(location_id text primary key references public.repo_diver_location_catalog_2026(location_id) on delete cascade,user_id uuid not null,username text not null,discovered_at timestamptz not null default now());
alter table public.repo_diver_location_catalog_2026 enable row level security;alter table public.repo_diver_artifact_catalog_2026 enable row level security;alter table public.repo_diver_location_progress_2026 enable row level security;alter table public.repo_diver_artifact_ledger_2026 enable row level security;alter table public.repo_diver_location_firsts_2026 enable row level security;
revoke all on public.repo_diver_location_catalog_2026,public.repo_diver_artifact_catalog_2026,public.repo_diver_location_progress_2026,public.repo_diver_artifact_ledger_2026,public.repo_diver_location_firsts_2026 from anon,authenticated;
insert into public.repo_diver_location_catalog_2026 select * from jsonb_to_recordset($j$[{"location_id":"coral_lantern_wreck","biome":"karamja","name":"CORAL LANTERN WRECK","location_type":"wreck","description":"A reef-claimed cutter with a warm lantern still glowing beneath the deck.","rooms_count":5,"sort_order":1},{"location_id":"sunscale_grotto","biome":"karamja","name":"SUNSCALE GROTTO","location_type":"cave","description":"A bright limestone cave where reflected reef-light reaches surprisingly deep.","rooms_count":5,"sort_order":2},{"location_id":"frozen_longship","biome":"fremennik","name":"THE FROZEN LONGSHIP","location_type":"wreck","description":"An ice-locked raider vessel sealed beneath a blue shelf.","rooms_count":5,"sort_order":3},{"location_id":"jarls_bell_cave","biome":"fremennik","name":"JARL'S BELL CAVE","location_type":"cave","description":"A glacial chamber built around a ceremonial bell lost to the fjord.","rooms_count":5,"sort_order":4},{"location_id":"drowned_windmill","biome":"kelp","name":"THE DROWNED WINDMILL","location_type":"ruin","description":"A river mill swallowed by the sea and wrapped in old kelp roots.","rooms_count":5,"sort_order":5},{"location_id":"rootbound_chapel","biome":"kelp","name":"ROOTBOUND CHAPEL","location_type":"ruin","description":"A tiny drowned chapel almost entirely consumed by the forest.","rooms_count":5,"sort_order":6},{"location_id":"sable_fen_observatory","biome":"morytania","name":"SABLE FEN OBSERVATORY","location_type":"facility","description":"A failed marsh-research station where the lower dome has flooded.","rooms_count":5,"sort_order":7},{"location_id":"drowned_apothecary","biome":"morytania","name":"THE DROWNED APOTHECARY","location_type":"ruin","description":"A sunken medicinal workshop full of sealed jars and handwritten remedies.","rooms_count":5,"sort_order":8},{"location_id":"prism_archive","biome":"coral","name":"THE PRISM ARCHIVE","location_type":"ruin","description":"A colour-lit reef archive whose crystal plates still hold etched records.","rooms_count":5,"sort_order":9},{"location_id":"roseglass_cavern","biome":"coral","name":"ROSEGLASS CAVERN","location_type":"cave","description":"A coral cavern glowing pink through translucent mineral walls.","rooms_count":5,"sort_order":10},{"location_id":"crown_of_varn","biome":"shipgrave","name":"THE CROWN OF VARN","location_type":"wreck","description":"A royal flagship split open across the Blackglass seabed.","rooms_count":5,"sort_order":11},{"location_id":"broken_admiral","biome":"shipgrave","name":"THE BROKEN ADMIRAL","location_type":"wreck","description":"A vast warship resting bow-down in the wreck field.","rooms_count":5,"sort_order":12},{"location_id":"hadal_relay_nine","biome":"abyssal","name":"HADAL RELAY NINE","location_type":"facility","description":"A deep-ocean relay station that stopped transmitting without warning.","rooms_count":5,"sort_order":13},{"location_id":"scar_mouth_caverns","biome":"abyssal","name":"SCAR MOUTH CAVERNS","location_type":"cave","description":"A chain of pressure-carved caves descending into the Abyssal Scar.","rooms_count":5,"sort_order":14},{"location_id":"glass_observatory","biome":"crystal","name":"THE GLASS OBSERVATORY","location_type":"facility","description":"A shattered research observatory built into the trench wall.","rooms_count":5,"sort_order":15},{"location_id":"lattice_vault","biome":"crystal","name":"THE LATTICE VAULT","location_type":"ruin","description":"A sealed crystal mechanism hidden behind a geometric mineral lattice.","rooms_count":5,"sort_order":16},{"location_id":"brimstone_pumpworks","biome":"volcanic","name":"BRIMSTONE PUMPWORKS","location_type":"facility","description":"An industrial thermal plant built where the vents are hottest.","rooms_count":5,"sort_order":17},{"location_id":"ashen_reliquary","biome":"volcanic","name":"THE ASHEN RELIQUARY","location_type":"ruin","description":"A scorched ceremonial chamber surrounded by active vent chimneys.","rooms_count":5,"sort_order":18},{"location_id":"fossil_basilica","biome":"shattered","name":"THE FOSSIL BASILICA","location_type":"ruin","description":"A collapsed sanctuary built around the ribs of something enormous.","rooms_count":5,"sort_order":19},{"location_id":"faultline_mine","biome":"shattered","name":"FAULTLINE MINE","location_type":"facility","description":"A mineral operation torn open when the shelf fractured.","rooms_count":5,"sort_order":20},{"location_id":"choir_vault","biome":"cathedral","name":"THE CHOIR VAULT","location_type":"ruin","description":"A sealed chamber beneath the nave where sound seems to linger in the stone.","rooms_count":5,"sort_order":21},{"location_id":"bell_tower_crypt","biome":"cathedral","name":"BELL TOWER CRYPT","location_type":"ruin","description":"A crypt beneath the fallen tower, accessible through a narrow breach.","rooms_count":5,"sort_order":22},{"location_id":"station_erebos","biome":"midnight","name":"STATION EREBOS","location_type":"facility","description":"An abandoned hadal station whose emergency lamps still cycle.","rooms_count":5,"sort_order":23},{"location_id":"black_choir_shaft","biome":"midnight","name":"THE BLACK CHOIR SHAFT","location_type":"cave","description":"A perfectly vertical trench cave that returns impossible sonar echoes.","rooms_count":5,"sort_order":24},{"location_id":"wayfarer_submersible","biome":"crossing","name":"THE WAYFARER SUBMERSIBLE","location_type":"wreck","description":"A long-range exploration craft adrift beneath the migration lanes.","rooms_count":5,"sort_order":25},{"location_id":"pilgrims_drop","biome":"crossing","name":"PILGRIM'S DROP","location_type":"cave","description":"An open-water sinkhole used by migrating giants as a navigation point.","rooms_count":5,"sort_order":26},{"location_id":"palace_of_tides","biome":"citadel","name":"THE PALACE OF TIDES","location_type":"ruin","description":"The monumental palace at the centre of the drowned imperial district.","rooms_count":5,"sort_order":27},{"location_id":"imperial_archive","biome":"citadel","name":"THE IMPERIAL ARCHIVE","location_type":"ruin","description":"A submerged records hall packed with sealed bronze document tubes.","rooms_count":5,"sort_order":28},{"location_id":"cinder_station","biome":"blackrift","name":"CINDER STATION","location_type":"facility","description":"A blackwater monitoring station sitting directly over the rift.","rooms_count":5,"sort_order":29},{"location_id":"forge_below","biome":"blackrift","name":"THE FORGE BELOW","location_type":"ruin","description":"A pre-imperial forge chamber heated by the volcanic fracture itself.","rooms_count":5,"sort_order":30},{"location_id":"icebound_fleet","biome":"pale","name":"THE ICEBOUND FLEET","location_type":"wreck","description":"Several ships trapped together beneath the Pale Sea ice.","rooms_count":5,"sort_order":31},{"location_id":"whiteglass_shrine","biome":"pale","name":"WHITEGLASS SHRINE","location_type":"ruin","description":"A frozen shrine visible only through a curtain of blue ice.","rooms_count":5,"sort_order":32},{"location_id":"horizon_array","biome":"endless","name":"THE HORIZON ARRAY","location_type":"facility","description":"A pelagic sensor array anchored over water with no visible floor.","rooms_count":5,"sort_order":33},{"location_id":"drift_cathedral","biome":"endless","name":"THE DRIFT CATHEDRAL","location_type":"ruin","description":"A colossal floating ruin drifting slowly through the open abyss.","rooms_count":5,"sort_order":34},{"location_id":"library_of_tides","biome":"ruins","name":"THE LIBRARY OF TIDES","location_type":"ruin","description":"A drowned library where stone shelves form a maze of collapsed archives.","rooms_count":5,"sort_order":35},{"location_id":"west_gate_temple","biome":"ruins","name":"WEST GATE TEMPLE","location_type":"ruin","description":"A ceremonial gatehouse temple guarding the western approach to the old city.","rooms_count":5,"sort_order":36}]$j$::jsonb) as x(location_id text,biome text,name text,location_type text,description text,rooms_count int,sort_order int)
on conflict(location_id) do update set biome=excluded.biome,name=excluded.name,location_type=excluded.location_type,description=excluded.description,rooms_count=excluded.rooms_count,sort_order=excluded.sort_order;
insert into public.repo_diver_artifact_catalog_2026(artifact_id,location_id,name,rarity,required_stage,lore)
select c.location_id||'_artifact_1',c.location_id,c.name||case c.location_type when 'wreck' then ' · CAPTAIN RELIC' when 'cave' then ' · SURVEY RELIC' when 'facility' then ' · DATA CORE' else ' · TIDE TABLET' end,
case when c.location_type='wreck' then 'historic' else 'rare' end,4,'Recovered from '||c.name||'. The object preserves evidence of the site before it was lost.'
from public.repo_diver_location_catalog_2026 c
on conflict(artifact_id) do update set name=excluded.name,rarity=excluded.rarity,required_stage=excluded.required_stage,lore=excluded.lore;
insert into public.repo_diver_artifact_catalog_2026(artifact_id,location_id,name,rarity,required_stage,lore)
select c.location_id||'_artifact_2',c.location_id,c.name||case c.location_type when 'wreck' then ' · BELL FRAGMENT' when 'cave' then ' · SEALED CACHE' when 'facility' then ' · IDENTITY PLATE' else ' · CEREMONIAL SEAL' end,
case when c.location_type in('cave','ruin') then 'exceptional' else 'rare' end,5,'Recovered from the deepest accessible chamber of '||c.name||'. It is one of the location''s defining finds.'
from public.repo_diver_location_catalog_2026 c
on conflict(artifact_id) do update set name=excluded.name,rarity=excluded.rarity,required_stage=excluded.required_stage,lore=excluded.lore;

create or replace function public.repo_diver_get_exploration_state() returns jsonb language plpgsql security definer set search_path='public','auth' as $$
declare u uuid:=auth.uid();locs jsonb;arts jsonb;
begin if u is null then raise exception 'You must be logged in';end if;
select coalesce(jsonb_agg(jsonb_build_object('location_id',c.location_id,'biome',c.biome,'name',c.name,'type',c.location_type,'description',c.description,'rooms_count',c.rooms_count,'sort_order',c.sort_order,'stage',coalesce(p.stage,0),'discovered',p.user_id is not null,'completed',p.completed_at is not null,'discovered_at',p.discovered_at,'completed_at',p.completed_at,'first_discovered_by',f.username,'artifact_total',(select count(*) from public.repo_diver_artifact_catalog_2026 a where a.location_id=c.location_id),'artifact_found',(select count(*) from public.repo_diver_artifact_catalog_2026 a join public.repo_diver_artifact_ledger_2026 l on l.artifact_id=a.artifact_id and l.user_id=u where a.location_id=c.location_id)) order by c.sort_order),'[]'::jsonb) into locs from public.repo_diver_location_catalog_2026 c left join public.repo_diver_location_progress_2026 p on p.location_id=c.location_id and p.user_id=u left join public.repo_diver_location_firsts_2026 f on f.location_id=c.location_id;
select coalesce(jsonb_agg(jsonb_build_object('artifact_id',a.artifact_id,'location_id',a.location_id,'name',a.name,'rarity',a.rarity,'required_stage',a.required_stage,'recovered',l.user_id is not null,'recovered_at',l.recovered_at,'identified',l.identified_at is not null,'identified_at',l.identified_at,'lore',case when l.identified_at is not null then a.lore else null end) order by a.location_id,a.required_stage),'[]'::jsonb) into arts from public.repo_diver_artifact_catalog_2026 a left join public.repo_diver_artifact_ledger_2026 l on l.artifact_id=a.artifact_id and l.user_id=u;
return jsonb_build_object('locations',locs,'artifacts',arts,'discovered_count',(select count(*) from public.repo_diver_location_progress_2026 where user_id=u),'completed_count',(select count(*) from public.repo_diver_location_progress_2026 where user_id=u and completed_at is not null),'artifact_count',(select count(*) from public.repo_diver_artifact_ledger_2026 where user_id=u));end $$;

create or replace function public.repo_diver_discover_location(p_run_id uuid,p_location_id text) returns jsonb language plpgsql security definer set search_path='public','auth' as $$
declare u uuid:=auth.uid();r public.repo_diver_runs%rowtype;c public.repo_diver_location_catalog_2026%rowtype;p public.repo_diver_location_progress_2026%rowtype;uname text;was_new boolean:=false;fu uuid;fn text;
begin if u is null then raise exception 'You must be logged in';end if;select * into r from public.repo_diver_runs where id=p_run_id and user_id=u and status='active' for update;if not found then raise exception 'Active expedition required';end if;select * into c from public.repo_diver_location_catalog_2026 where location_id=p_location_id;if not found or c.biome<>r.biome then raise exception 'Location does not belong to this expedition';end if;select * into p from public.repo_diver_location_progress_2026 where user_id=u and location_id=p_location_id for update;if not found then insert into public.repo_diver_location_progress_2026(user_id,location_id,last_run_id) values(u,p_location_id,p_run_id) returning * into p;was_new:=true;else update public.repo_diver_location_progress_2026 set last_run_id=p_run_id,updated_at=now() where user_id=u and location_id=p_location_id returning * into p;end if;select username into uname from public.characters where user_id=u order by username nulls last limit 1;insert into public.repo_diver_location_firsts_2026(location_id,user_id,username) values(p_location_id,u,coalesce(uname,'Diver')) on conflict(location_id) do nothing;select user_id,username into fu,fn from public.repo_diver_location_firsts_2026 where location_id=p_location_id;return jsonb_build_object('stage',p.stage,'new_discovery',was_new,'first_discovery',fu=u,'first_discovered_by',fn);end $$;

create or replace function public.repo_diver_advance_location(p_run_id uuid,p_location_id text,p_expected_stage int) returns jsonb language plpgsql security definer set search_path='public','auth' as $$
declare u uuid:=auth.uid();r public.repo_diver_runs%rowtype;c public.repo_diver_location_catalog_2026%rowtype;p public.repo_diver_location_progress_2026%rowtype;done boolean;
begin if u is null then raise exception 'You must be logged in';end if;select * into r from public.repo_diver_runs where id=p_run_id and user_id=u and status='active' for update;if not found then raise exception 'Active expedition required';end if;select * into c from public.repo_diver_location_catalog_2026 where location_id=p_location_id;if not found or c.biome<>r.biome then raise exception 'Location does not belong to this expedition';end if;insert into public.repo_diver_location_progress_2026(user_id,location_id,last_run_id) values(u,p_location_id,p_run_id) on conflict(user_id,location_id) do nothing;select * into p from public.repo_diver_location_progress_2026 where user_id=u and location_id=p_location_id for update;if p_expected_stage<1 or p_expected_stage>c.rooms_count then raise exception 'Invalid location stage';end if;if p.stage>=p_expected_stage then return jsonb_build_object('stage',p.stage,'duplicate',true,'completed',p.completed_at is not null);end if;if p_expected_stage<>p.stage+1 then raise exception 'Location stages must be completed in sequence';end if;done:=p_expected_stage>=c.rooms_count;update public.repo_diver_location_progress_2026 set stage=p_expected_stage,completed_at=case when done then coalesce(completed_at,now()) else completed_at end,last_run_id=p_run_id,updated_at=now() where user_id=u and location_id=p_location_id returning * into p;return jsonb_build_object('stage',p.stage,'duplicate',false,'completed',p.completed_at is not null);end $$;

create or replace function public.repo_diver_recover_artifact(p_run_id uuid,p_location_id text,p_artifact_id text) returns jsonb language plpgsql security definer set search_path='public','auth' as $$
declare u uuid:=auth.uid();r public.repo_diver_runs%rowtype;c public.repo_diver_location_catalog_2026%rowtype;a public.repo_diver_artifact_catalog_2026%rowtype;p public.repo_diver_location_progress_2026%rowtype;ins text;
begin if u is null then raise exception 'You must be logged in';end if;select * into r from public.repo_diver_runs where id=p_run_id and user_id=u and status='active' for update;if not found then raise exception 'Active expedition required';end if;select * into c from public.repo_diver_location_catalog_2026 where location_id=p_location_id;if not found or c.biome<>r.biome then raise exception 'Location does not belong to this expedition';end if;select * into a from public.repo_diver_artifact_catalog_2026 where artifact_id=p_artifact_id and location_id=p_location_id;if not found then raise exception 'Invalid artifact for this location';end if;select * into p from public.repo_diver_location_progress_2026 where user_id=u and location_id=p_location_id;if not found or p.stage<a.required_stage then raise exception 'The required chamber has not been reached';end if;insert into public.repo_diver_artifact_ledger_2026(user_id,artifact_id,run_id) values(u,p_artifact_id,p_run_id) on conflict(user_id,artifact_id) do nothing returning artifact_id into ins;return jsonb_build_object('artifact_id',p_artifact_id,'name',a.name,'rarity',a.rarity,'saved',ins is not null,'duplicate',ins is null);end $$;

create or replace function public.repo_diver_identify_artifact(p_artifact_id text) returns jsonb language plpgsql security definer set search_path='public','auth' as $$
declare u uuid:=auth.uid();a public.repo_diver_artifact_catalog_2026%rowtype;l public.repo_diver_artifact_ledger_2026%rowtype;
begin if u is null then raise exception 'You must be logged in';end if;select * into a from public.repo_diver_artifact_catalog_2026 where artifact_id=p_artifact_id;if not found then raise exception 'Artifact not found';end if;select * into l from public.repo_diver_artifact_ledger_2026 where user_id=u and artifact_id=p_artifact_id for update;if not found then raise exception 'Recover this artifact first';end if;update public.repo_diver_artifact_ledger_2026 set identified_at=coalesce(identified_at,now()) where user_id=u and artifact_id=p_artifact_id returning * into l;return jsonb_build_object('artifact_id',a.artifact_id,'name',a.name,'rarity',a.rarity,'lore',a.lore,'identified',true,'identified_at',l.identified_at);end $$;

grant execute on function public.repo_diver_get_exploration_state() to authenticated;grant execute on function public.repo_diver_discover_location(uuid,text) to authenticated;grant execute on function public.repo_diver_advance_location(uuid,text,int) to authenticated;grant execute on function public.repo_diver_recover_artifact(uuid,text,text) to authenticated;grant execute on function public.repo_diver_identify_artifact(text) to authenticated;
